using System.Text.Json;
using System.Text.Json.Nodes;
using ModelContextProtocol.Protocol;
using NanoCAD.Contracts;

namespace NanoCAD.McpServer;

public static class ToolCatalog
{
    // Server-local visual reads never enter the CAD named-pipe operation allowlist.
    public static string[] OperationNames { get; } = Wire.Operations.Append("capture_view").ToArray();
    private static readonly Dictionary<string, JsonElement> InputContracts = new(StringComparer.Ordinal);
    public static IList<Tool> Tools { get; } = OperationNames.Select(operation =>
    {
        var tool = Build(operation);
        tool.Description = ToolUsage.Purpose(operation) + ToolUsage.Contract(operation) + (operation switch
        {
            "query_objects" => TargetedReadSchema407.QueryDescription,
            "inspect_objects" => TargetedReadSchema407.InspectDescription + EraseAssessmentSchema444.Description,
            _ => ""
        });
        if (ReadPreparation433.Readers.Contains(operation, StringComparer.Ordinal)) tool.Description += ReadPreparationSchema433.Description;
        var input = SchemaCompactor.InlineInput(ReadPreparationSchema433.Input(operation, tool.InputSchema));
        InputContracts.Add(operation, input);
        tool.InputSchema = SchemaCompactor.PublishInput(operation, input);
        if (tool.OutputSchema is { } output) tool.OutputSchema = SchemaCompactor.Compact(output);
        return tool;
    }).Append(GuidanceCatalog.Tool()).ToArray();
    private static readonly Dictionary<string, string> OperationsByToolName = OperationNames.Append("get_guidance")
        .ToDictionary(operation => "nanocad." + operation, StringComparer.Ordinal);

    public static bool TryResolveOperation(string toolName, out string operation) =>
        OperationsByToolName.TryGetValue(toolName, out operation!);

    internal static JsonElement InputContract(string operation) => InputContracts[operation];
    internal static string DetailedDescription(string operation) => Build(operation).Description ?? "";
